const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(t,r)=>`<a class="button secondary" href="#/${h(r)}">${h(t)}</a>`;
const btn=(t,action,attrs='',on=false)=>`<button type="button" class="button ${on?'':'secondary'}" data-action="${action}" ${attrs}>${h(t)}</button>`;
const attrs=(q,kind,scope)=>`data-question="${h(q.id)}" data-kind="${kind}" data-scope="${h(scope)}"`;
const intro=(title,copy)=>`<header class="page-intro"><div><span class="eyebrow">YOUR POSSIBILITIES</span><h1>${h(title)}</h1><p class="intro-copy">${h(copy)}</p></div></header>`;
const workDetail=(s,r)=>{if(r.o.noncollege087)return `<section class="guide-input-panel"><h1>${h(r.o.title)}</h1><p>${h(r.o.summary)}</p><p>${h(r.o.preparation.typicalEducation[0])}</p><p><strong>$${Math.round(r.o.salary.entry).toLocaleString()} / year</strong> · lower-paid-worker proxy · ${h(r.o.salary.geography)} · ${h(r.o.salary.period)}</p><p>${h(r.o.salary.basis)}</p>${link('Check this career’s interests','journey/clarify/'+r.id+'/0')} <a href="${h(r.o.sourceURL)}" target="_blank" rel="noopener">Career source ↗</a></section>`;const row={id:r.id,o:r.o,kind:'chosen',rating:r.specific.supported?'Specific interests supported':'Exploration option',basis:'chosen',evidence:r.specific.evidence,reasons:r.specific.evidence.map(x=>x.text),confirmation:{confirmed:r.specific.supported},interestMatch:{r:r.r},supported:r.specific.supported};let html=resultCareerPanel(s,row,{choose:true,standalone:true});if(r.o.expandedDegree)html=html.replace(/<section class="match-reasons">[\s\S]*?<\/section>/,'<section class="match-reasons"><h3>'+h(r.band)+'</h3><p>The evidence and unresolved questions above use all saved answers. Broad correlation and specific interests are assessed separately.</p></section>');return html.replace(/<button class="button" data-action="journey-plan"[^>]*>[\s\S]*?<\/button>/g,'').replaceAll('#/journey/degree-check/'+r.id,'#/journey/clarify/'+r.id+'/0').replaceAll('#/journey/check-career/'+r.id+'/0','#/journey/clarify/'+r.id+'/0');};
const money=n=>Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n):'Pay needs verification';
function lifestyleLens(s,result){if(!s.guide?.lifestylePreset)return `<section class="guide-input-panel"><h2>Picture the life you want</h2><p>Your lifestyle goal helps compare pay and training routes while every career stays open to explore.</p>${link('Start with lifestyle','journey/lifestyle')}</section>`;const goal=lifestyleIncomeRange(s.finance.lifestyle);if(!goal)return '<section class="guide-input-panel"><h2>Review your lifestyle goal</h2><p>Some budget inputs need attention before we can compare pay.</p>'+link('Review lifestyle inputs','journey/lifestyle')+'</section>';const rows=result.rows.map(r=>({...r,budget:explorerBudget(s,r.o)})),degree=rows.filter(r=>degreeRoute059(r.o)&&r.budget.covers===true&&!r.specific.contrary.length),supported=degree.filter(r=>r.specific.supported),discovery=degree.filter(r=>!r.specific.supported&&r.r!==null&&r.r>=.608).slice(0,4),gaps=rows.filter(r=>r.specific.supported&&!r.degree&&r.budget.covers===false).slice(0,3),careerLink=r=>'<li><a href="#/journey/profession/'+r.id+'">'+h(r.o.title)+'</a> · '+money(r.budget.amount)+' at the assessed first-paid stage · '+h(r.budget.reason)+'</li>';return `<section class="guide-input-panel"><h2>Your lifestyle goal</h2><p><strong>${money(goal.low)}–${money(goal.high)} a year before tax</strong> · based on the lifestyle you pictured.</p>${link('Review my lifestyle','journey/lifestyle-summary')}<h3>College and graduate routes to compare</h3>${supported.length?'<p>These careers have specific interest support and assessed pay that could cover this budget:</p><ul>'+supported.slice(0,6).map(careerLink).join('')+'</ul>':'<p>No specifically supported degree career in this view has assessed pay that covers the goal yet. Every learning route remains available.</p>'}${discovery.length?'<details><summary>Degree connections worth clarifying · budget could fit</summary><p>These have broad interest connections and assessed budget coverage. Their profession-specific interests still need clarification.</p><ul>'+discovery.map(careerLink).join('')+'</ul></details>':''}${gaps.length?'<details><summary>Other interest fits with a budget gap</summary><p>These remain valid interest options; their assessed first-paid-stage pay falls short of your goal.</p><ul>'+gaps.map(careerLink).join('')+'</ul></details>':''}<p>Pay, study costs, aid and loan payments need their own comparison. Unknown pay stays unassessed; a higher salary does not create an interest match.</p></section>`;}
const returnLink=scope=>link('Return to careers','journey/explore'+(scope&&scope!=='all'?'?scope='+encodeURIComponent(scope):''));
export function explorerCard(r,s,scope='all'){const e=r.specific,saved=s.careerLibrary?.saved?.includes(r.id);return `<article class="guide-input-panel"><span class="time-chip">${h(r.band)}</span><h2>${h(r.o.title)}</h2><p>${h(r.o.summary)}</p><p><strong>${h(explorerEducation(r.o))}</strong>${r.o.requiresExperience?' · Experienced destination; investigate earlier roles':''}</p><p>${r.r===null?'No comparable broad score is available for this profile and career.':'Broad interest correlation r = '+r.r.toFixed(3)+' · six interest themes; this is not a probability or aptitude score.'}</p>${r.activityTopics?.length&&!e.supported?'<p class="muted">Your activity interests connect here. This remains an invitation to explore, not a confirmed profession match.</p>':''}${e.inferred?'<p class="muted">This fictional model includes profile-inferred responses.</p>':''}<details><summary>Why this appears · evidence and uncertainty</summary><p>${h(e.requirement)}</p>${e.evidence.length?'<ul>'+e.evidence.map(x=>'<li>'+h(x.text)+'<small> · '+h(x.domain)+' · '+h(x.source)+'</small></li>').join('')+'</ul>':'<p>No profession-specific supporting answers yet. Broad similarity is an invitation to explore.</p>'}${e.contrary.length?'<p><strong>Mixed interests:</strong> an essential responsibility did not appeal.</p><ul>'+e.contrary.map(x=>'<li>'+h(x.prompt)+'</li>').join('')+'</ul>':''}${e.missing.length?'<p>Still unclear:</p><ul>'+e.missing.map(x=>'<li>'+h(x.prompt)+'</li>').join('')+'</ul>':''}<p>Current skills, education, finances and interests are separate considerations. Unfamiliar work remains available.</p></details><div class="dialog-actions">${btn(saved?'Saved':'Save for later','explorer-save',`data-id="${r.id}" aria-pressed="${!!saved}"`)}${link('Explore the work','journey/profession/'+r.id)}${link('Clarify this profession','journey/clarify/'+r.id+'/0?scope='+scope)}${btn('Add an exploration plan','explorer-plan',`data-id="${r.id}"`)}</div></article>`;}
export function openExplorerPage(route,s){const canonical=resolveExplorerRoute(s,route)||route,[path,query='']=canonical.split('?'),p=path.split('/'),params=new URLSearchParams(query),scope=params.get('scope')||'all';
 if(p[1]==='match-followup'&&/^\d+$/.test(p[2]))return automaticFollowupPage083(s,Number(p[2]));
 if(path==='plan'){const o=occupationById(s.guide?.primaryCareer);if(!o)return intro('Your plan can start anywhere.','Explore careers and save the possibilities you want to investigate.')+returnLink();const r=explorerResults(s).rows.find(r=>r.id===o.id);return intro('Your exploration plan',o.title+' is your chosen possibility. You can change direction as you learn more.')+`<section class="guide-input-panel"><p><strong>${h(r?.band||'Your choice')}</strong> · choosing a plan does not establish an interest match.</p><div class="dialog-actions">${link('Review this career','journey/profession/'+o.id)}${returnLink()}${link('Optional lifestyle comparison','journey/lifestyle')}${o.expandedDegree?'':link('Plan education funding','education-funding/'+o.id)}</div></section><section><h2>My saved steps and notes</h2>${(s.actions||[]).map(a=>`<article class="guide-input-panel"><label><input type="checkbox" data-action-check="${h(a.id)}" ${a.done?'checked':''}><strong>${h(a.title)}</strong></label><p>${h(a.detail)}</p><label>My notes<textarea data-plan-action="${h(a.id)}" data-plan-field="notice" maxlength="2000">${h(a.notice||'')}</textarea></label></article>`).join('')}<div class="dialog-actions">${btn('Print / save PDF','print')}${btn('Export my full draft','export')}</div></section><h2>Keep exploring</h2><p>Every career remains available, including other fields and learning routes.</p>${returnLink()}`;}
 if(p[1]==='profession'&&p.length===3){const r=explorerResults(s).rows.find(x=>x.id===p[2]);if(!r)return returnLink();const row={id:r.id,o:r.o,kind:'chosen',rating:r.specific.supported?'Specific interests supported':'Exploration option',basis:'chosen',evidence:r.specific.evidence,reasons:r.specific.evidence.map(x=>x.text),confirmation:{confirmed:r.specific.supported},interestMatch:{r:r.r},supported:r.specific.supported};return intro(r.o.title,'Explore the work, preparation and financial assumptions, then decide what you want to investigate next.')+returnLink()+explorerCard(r,s)+`<details class="guide-input-panel"><summary>Work, preparation, pay and lifestyle details</summary>${workDetail(s,r)}</details>`;}
 if(path==='journey/interest-intro')return intro('Keep your possibilities open.','With your lifestyle goal in view, explore your interests across every field. You can return to any answer.')+`<section class="guide-input-panel"><h2>A broad starting picture</h2><p>The 60-item O*NET® Interest Profiler asks how much you would enjoy different activities. Consider your interest, rather than whether you already know how to do them. Your results lead to an open career explorer, where your lifestyle goal helps compare pay and learning routes.</p>${link('Start / resume interest questions','journey/profile')} ${link('Browse all careers now','journey/explore')}<details><summary>Official instrument and attribution</summary><p>${h(onetInstrument.attribution)}</p><a href="${h(onetInstrument.scoringURL)}" target="_blank" rel="noopener">Scoring manual</a></details></section>`;
 if(p[1]==='interest'&&/^\d+$/.test(p[2])){const i=Number(p[2]),q=onetQuestions[i];if(!q)return intro('Question not found.','Return to your career explorer.')+returnLink();return intro('How would you feel about this activity?',`O*NET® Interest Profiler · ${i+1} of 60`)+`<section class="guide-input-panel interest-question-card"><h2 id="interest-activity">${h(q.text)}</h2><fieldset class="interest-answer-group" aria-labelledby="interest-activity"><legend class="sr-only">Choose how you feel about this activity</legend><div class="interest-response-grid">${onetResponseOptions.map(o=>btn(o.label,'explorer-official',`data-question="${q.id}" data-value="${o.value}" data-index="${i}" aria-pressed="${s.profileJourney?.officialInterest?.answers?.[q.id]===o.value}"`,s.profileJourney?.officialInterest?.answers?.[q.id]===o.value)).join('')}</div></fieldset>${i?'<nav class="interest-question-nav" aria-label="Question navigation">'+link('← Previous','journey/interest/'+(i-1))+'</nav>':''}<small class="interest-attribution">${h(onetInstrument.attribution)}</small></section>`;}
 if(p[1]==='strengths'){const i=Number(p[2])||0,q=skillQuestions[i];if(!q)return returnLink();return intro('Strengths you can develop',`Optional · ${i+1} of ${skillQuestions.length}. Experience is a learning clue, never a limit on career access.`)+`<section class="guide-input-panel"><h2>${h(q.prompt)}</h2>${skillResponseOptions.map(o=>btn(o.label,'explorer-skill',`data-index="${i}" data-id="${q.id}" data-value="${o.id}"`,s.profileJourney.skills?.[q.id]?.level===o.id)).join(' ')}<p>${returnLink()}</p></section>`;}
 if(['refine','field-survey','clarify'].includes(p[1])){const kind=p[1]==='refine'?'facet':p[1]==='field-survey'?'field':'profession',surveyScope=kind==='facet'?'all':p[2],i=Number(p[kind==='facet'?2:3])||0,qs=kind==='facet'?explorerQuestions:kind==='field'?explorerFieldQuestions(surveyScope):explorerCareerQuestions(surveyScope),q=qs[i];if(!q)return intro('This exploration is complete.','Your earlier answers are preserved. You can review the results or explore another field.')+returnLink(kind==='field'?surveyScope:scope);const a=kind==='facet'?s.explorer053?.facetAnswers?.[q.id]:explorerAnswer(s,kind,surveyScope,q),specific=q.kind==='specific',common=attrs(q,kind,surveyScope)+` data-index="${i}" data-return="${h(kind==='field'?surveyScope:scope)}"`;
 const options=kind==='facet'?[[5,'Very interested'],[4,'Interested'],[3,'Unsure'],[2,'Not very interested'],[1,'Not for me'],['unfamiliar','I need an example']]:specific?[['yes','I would like to learn this'],['no','This does not interest me'],['unsure','Unsure'],['unfamiliar','I need to learn more']]:null;
 return intro(kind==='field'?'Explore within '+(careerFamilies.find(f=>f.id===surveyScope)?.title||surveyScope):kind==='facet'?'What holds your attention?':'Explore this profession',`Optional · ${i+1} of ${qs.length}. ${kind==='facet'?'Original reflection questions; these are separate from your official interest score.':'All relevant earlier answers count. You can like more than one example.'}`)+`<section class="guide-input-panel"><h2>${h(q.prompt)}</h2>${options?'<div class="dialog-actions">'+options.map(([v,t])=>btn(t,'explorer-response',common+` data-value="${v}"`,(kind==='facet'?a?.value:a?.response)===v)).join('')+'</div>':`<form id="explorer-answer"><fieldset><legend>Choose any examples that appeal</legend>${q.options.map(o=>`<label class="followup-choice"><input type="checkbox" name="explorer-option" value="${o.id}" ${a?.selected?.includes(o.id)?'checked':''}><span>${h(o.text)}</span></label>`).join('')}</fieldset><div class="followup-actions">${btn('Continue →','explorer-task',common)} ${['unsure','unfamiliar','none'].map(v=>btn(v==='none'?'None appeal':v==='unsure'?'Unsure':'I need to learn more','explorer-task',common+` data-feedback="${v}"`)).join(' ')}</div><p role="status" id="explorer-error"></p></form>`}<p>${i?link('Previous',p.slice(0,kind==='facet'?2:3).join('/')+'/'+(i-1)+'?scope='+scope):''} ${returnLink(kind==='field'?surveyScope:scope)}</p>${kind==='facet'&&(i+1)%8===0?'<p>End of this eight-question round. You can return to results now or continue when ready.</p>':''}</section>`;}
 if(path!=='journey/explore')return null;
 const options={scope,education:params.get('education')||'all',query:params.get('q')||'',sort:params.get('sort')||'evidence',saved:params.get('saved')==='1'},result=educationView059(explorerResults(s,{...options,education:'all'}),options.education),page=Math.min(Math.max(1,Number(params.get('page'))||1),Math.max(1,Math.ceil(result.total/12))),title=scope==='all'?'Your career possibilities':careerFamilies.find(f=>f.id===scope)?.title||'Choose a field';
 const pageLink=n=>{const v=new URLSearchParams(params);v.set('page',n);return 'journey/explore?'+v;};
 return intro(title,'Keep your possibilities open. Explore broadly, save what interests you, and clarify a field or profession when you want more detail.')+`<section class="guide-input-panel"><p>${result.profile.complete?'60 official interest responses saved.':'Official interest profile: '+result.profile.answered+' of 60 responses saved.'} ${result.profile.complete?'<details><summary>Your six broad interest scores</summary><ul>'+Object.values(result.profile.groups).map(g=>'<li>'+h(g.theme)+': '+g.raw+' / 40</li>').join('')+'</ul><p>Interest totals describe preferences, not ability or percentile ranks.</p></details>':''} ${result.profile.flat||result.profile.nearFlat?'Your responses are very similar across themes, so a ranked correlation would be unreliable. Explore by interest evidence or browse fields.':''}</p><p>${result.total} careers in this view · ${result.rows.filter(r=>r.specific.supported).length} with specific interests supported. Pagination does not remove other careers.</p><form id="explorer-filters"><div class="form-row"><label>Field<select name="scope"><option value="all">All fields</option>${careerFamilies.map(f=>`<option value="${f.id}" ${scope===f.id?'selected':''}>${h(f.title)}</option>`).join('')}</select></label><label>Education<select name="education"><option value="all">All learning routes</option><option value="degree" ${options.education==='degree'?'selected':''}>College and graduate professions</option>${[['work','Learn at work'],['apprenticeship','Apprenticeship'],['program','Associate / specialist program'],['college','Bachelor’s degree'],['graduate','Graduate / professional']].map(([key,label])=>`<option value="${key}" ${options.education===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Order<select name="sort"><option value="evidence">Specific evidence, then activity connections and broad correlation</option><option value="correlation" ${options.sort==='correlation'?'selected':''}>Raw broad interest correlation</option></select></label></div><label>Search careers<input type="search" name="q" value="${h(options.query)}" placeholder="Try engineering, medicine, writing…"></label><label><input type="checkbox" name="saved" value="1" ${options.saved?'checked':''}> Only my saved careers</label><button class="button" type="submit">Apply view</button></form><div class="dialog-actions">${link('Review broad interest questions','journey/profile')}${link('Explore underlying interests','journey/refine/'+Math.max(0,explorerQuestions.findIndex(q=>!s.explorer053?.facetAnswers?.[q.id])))}${link('Reflect on strengths','journey/strengths/0')}${scope!=='all'&&result.scope!=='invalid'?link('Optional survey within this field','journey/field-survey/'+scope+'/0'):''}</div><p>Your lifestyle goal highlights financially promising routes. Interest evidence stays separate, so higher pay never turns a weak fit into a match.</p></section>${topicsPanel056(s)}${soundPanel056(s)}${lifestyleLens(s,result)}${explorationPanel059(s,result,scope)}${Object.keys(s.explorer053?.facetAnswers||{}).length?'<details class="guide-input-panel"><summary>Your underlying-interest reflections</summary><p>Original reflections: useful clues for exploration, without changing official scores or confirming professions.</p><ul>'+explorerQuestions.filter(q=>s.explorer053.facetAnswers[q.id]).map(q=>'<li>'+h(q.prompt)+' · response '+h(s.explorer053.facetAnswers[q.id].value)+'</li>').join('')+'</ul></details>':''}<div class="explorer-grid">${result.rows.slice((page-1)*12,page*12).map(r=>explorerCard(r,s,scope)).join('')||'<section class="guide-input-panel"><h2>No careers in this view.</h2><p>Change the filters or explore another field. We do not substitute unrelated careers.</p>'+link('Clear filters','journey/explore')+'</section>'}</div><nav class="dialog-actions" aria-label="Career pages">${page>1?link('Previous careers',pageLink(page-1)):''}<span>Page ${page} of ${Math.max(1,Math.ceil(result.total/12))}</span>${page*12<result.total?link('Next careers',pageLink(page+1)):''}</nav><section><h2>You also have options in these fields</h2><p>Every field stays available. These are its leading career connections, with the same evidence rules.</p><div class="explorer-grid">${explorerFieldSummary(s).map(f=>`<article class="guide-input-panel"><h3>${h(f.title)}</h3><p>${f.count} professions available</p><ul>${f.careers.map(r=>'<li>'+h(r.o.title)+' · '+h(r.band)+'</li>').join('')}</ul>${link('Explore this field','journey/explore?scope='+f.id)}</article>`).join('')}</div></section>`;
}
